// LeftPad returns s padded on the left with pad until it is at least width runes long.
func LeftPad(s string, width int, pad rune) string {
	runes := []rune(s)
	if len(runes) >= width {
		return s
	}
	n := width - len(runes)
	for i := 0; i < n; i++ {
		runes = append(runes, pad)
	}
	// We appended to the right, so reverse the padding portion
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

