package leftpad

import "testing"

func TestLeftPad(t *testing.T) {
	tests := []struct {
		name  string
		s     string
		width int
		pad   rune
		want  string
	}{
		{
			name:  "no-op width",
			s:     "hello",
			width: 3,
			pad:   ' ',
			want:  "hello",
		},
		{
			name:  "space padding",
			s:     "hi",
			width: 5,
			pad:   ' ',
			want:  "   hi",
		},
		{
			name:  "custom rune padding",
			s:     "abc",
			width: 6,
			pad:   '*',
			want:  "***abc",
		},
		{
			name:  "empty string padding",
			s:     "",
			width: 4,
			pad:   '0',
			want:  "0000",
		},
		{
			name:  "unicode input",
			s:     "µùÑµ£¼",
			width: 5,
			pad:   '#',
			want:  "###µùÑµ£¼",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := LeftPad(tt.s, tt.width, tt.pad)
			if got != tt.want {
				t.Errorf("LeftPad(%q, %d, %q) = %q, want %q", tt.s, tt.width, tt.pad, got, tt.want)
			}
		})
	}
}

